CREATE TEMP TABLE stage_events (
  qid text PRIMARY KEY, title text, summary text,
  start_year int, start_month smallint, start_day smallint,
  end_year int, end_month smallint, end_day smallint,
  precision date_precision, display_date text, importance smallint, url text,
  event_id bigint
) ON COMMIT DROP;
CREATE TEMP TABLE stage_links (qid text, term_slug text, relevance real, is_primary boolean) ON COMMIT DROP;
CREATE TEMP TABLE stage_tags (qid text, tag_slug text) ON COMMIT DROP;

INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q787240', 'Gambian republic referendum, 1965', 'A referendum on becoming a republic was held in the Gambia on 24 November 1965. If the referendum had passed, the post of president would have replaced Elizabeth II as head of state, and thus eliminated the post of Governor-General.', 1965, 11, 24, NULL, NULL, NULL, 'day', '24 November 1965', 34, 'https://en.wikipedia.org/wiki/1965_Gambian_republic_referendum'),
  ('Q1618793', 'Gambian republic referendum, 1970', 'A referendum on becoming a republic was held in the Gambia in April 1970. The changes resulted in the creation of the post of President to replace Elizabeth II as head of state, thus eliminating the post of Governor-General.', 1970, 4, 20, NULL, NULL, NULL, 'day', '20 April 1970', 39, 'https://en.wikipedia.org/wiki/1970_Gambian_republic_referendum'),
  ('Q4589458', '1994 Gambian coup d''état', 'In the 1994 Gambian coup d''état, a group of soldiers led by 29-year-old Lieutenant Yahya Jammeh seized power in a coup d''état on the morning of 22 July, ousting Dawda Jawara, who had been President of The Gambia since it became a Republic in 1970. The coup plotters dissolved the government, arrested government members, and abolished the constitution.', 1994, 7, 22, NULL, NULL, NULL, 'day', '22 July 1994', 39, 'https://en.wikipedia.org/wiki/1994_Gambian_coup_d''%C3%A9tat');

